// TH14 synthetic vocabulary: native type6 -> target 6, native type8 -> target 8.
const TH14_RING_BALL: int = 448;
const TH14_RICE: int = 480;

// TH14 v1.00b st07::MainSub00/MainSub00b; source 636-667 plus GirlA01/GirlB01 helpers.
// Card frame 0 is main(); source MainSub00 entry runs at card frame 122.
const TIME_LIMIT: int = 2124;
const OPENING_BUFFER: int = 120;

async sub pattern() {
    // Source 639 wait(80); 640 MainSub00b async.
    wait(OPENING_BUFFER);
    wait(80);
    spawn b01_wave();
    // Source 641-647: left GirlA01, one every 15 frames, 16 total.
    for left in 0..16 {
        _ = spawn_enemy(-160fx, -32fx, 110, 0, 1000, 0, girl_a(0));
        wait(15);
    }
    // Source 648-655: wait(80), then right mirrored GirlA01, 16 total.
    wait(80);
    for right in 0..16 {
        _ = spawn_enemy(160fx, -32fx, 110, 0, 1000, 0, girl_a(1));
        wait(15);
    }
}

async sub b01_wave() {
    // Source 659-666; the two waits before the second birth stay separate.
    wait(20);
    _ = spawn_enemy(160fx, -32fx, 400, 0, 1000, 0, girl_b(0));
    wait(230);
    wait(80);
    _ = spawn_enemy(-160fx, -32fx, 400, 0, 1000, 0, girl_b(1));
}

async sub girl_a(mirror: int) {
    set_invuln(65535);
    // Source 171-172: setHurtbox(24,24)/setHitbox(16,16), ordinary circle radius = width/2.
    set_hurtbox(12fx);
    set_hitbox(8fx);
    // Source 173: GirlA01_at2 async, before the movement writes.
    spawn girl_a_shots();
    // Source 174-182; mirror reflects x, so the target angle is 180deg - source angle.
    move_vel(0, 90deg, 4fx, EASE_LINEAR);
    if mirror == 0 {
        move_vel(120, -11.25deg, 3fx, EASE_QUAD_IN);
        wait(120);
        move_vel(60, 11.25deg, 4fx, EASE_QUAD_OUT);
    } else {
        move_vel(120, 191.25deg, 3fx, EASE_QUAD_IN);
        wait(120);
        move_vel(60, 168.75deg, 4fx, EASE_QUAD_OUT);
    }
    loop { wait(1000); }
}

async sub girl_a_shots() {
    // Source 189-196: native type8 rice color6, aimed, 1 way x 2 layers at speeds 5 and 4.
    // ANIM a=1 keeps the -4*speed spawn retreat; layers need separate distances.
    sh_reset(0);
    sh_sprite(0, TH14_RICE, 6);
    sh_aim(0, 1);
    sh_ring(0, 0);
    sh_count(0, 1, 1);
    sh_angle(0, 0deg, 3deg);
    sh_speed(0, 5fx, 0fx);
    sh_dist(0, -20fx);
    sh_reset(1);
    sh_sprite(1, TH14_RICE, 6);
    sh_aim(1, 1);
    sh_ring(1, 0);
    sh_count(1, 1, 1);
    sh_angle(1, 0deg, 3deg);
    sh_speed(1, 4fx, 0fx);
    sh_dist(1, -16fx);
    // Source's second EX record type1 SPEEDUP carries only -999999 sentinels; no motor write.
    // Source 197-203: 100 volleys, 10 frames apart.
    for i in 0..100 {
        sh_fire(0);
        sh_fire(1);
        wait(10);
    }
}

async sub girl_b(mirror: int) {
    set_invuln(65535);
    set_hurtbox(12fx);
    set_hitbox(8fx);
    // Source 292-298; mirrored variant reflects x.
    move_vel(0, 90deg, 3fx, EASE_LINEAR);
    if mirror == 0 {
        move_vel(80, 101.25deg, 0fx, EASE_QUAD_IN);
    } else {
        move_vel(80, 78.75deg, 0fx, EASE_QUAD_IN);
    }
    wait(60);
    // Source 295: GirlB01_at2 async.
    spawn girl_b_shots();
    wait(120);
    if mirror == 0 {
        move_vel(60, 168.75deg, 1fx, EASE_LINEAR);
    } else {
        move_vel(60, 11.25deg, 1fx, EASE_LINEAR);
    }
    loop { wait(1000); }
}

async sub girl_b_shots() {
    // Source 309-315: native type6 ring ball color2, aimed 3-way fan 10deg, speed3.
    sh_reset(0);
    sh_sprite(0, TH14_RING_BALL, 2);
    sh_aim(0, 1);
    sh_ring(0, 0);
    sh_count(0, 3, 1);
    sh_speed(0, 3fx, 0fx);
    sh_dist(0, -12fx); // ANIM a=1 keeps the -4*3 retreat.
    // Source 316-331: diffI picks the hardest value 32 for Extra; 32 rounds of 4 volleys/5f + 40f.
    for round in 0..32 {
        for volley in 0..4 {
            var off: int = (rand(65536) - 32768) / 64; // RANDRAD/64 = +-pi/64
            sh_angle(0, off as angle, 10deg);
            sh_fire(0);
            wait(5);
        }
        wait(40);
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
